tool_calls:
mkdir -p solid-job && cat > solid-job/design.json <<'EOF'
{
  "sources": [
    "spacer block dimensions 30 x 20 x 12 mm and hole diameter 5 mm straight down through middle of 30x20 face"
  ],
  "commands": [
    {
      "command": "solid.box",
      "params": {
        "length": 30,
        "width": 20,
        "height": 12,
        "corner": [0, 0, 0],
        "body_name": "Spacer"
      }
    },
    {
      "command": "solid.cylinder",
      "params": {
        "diameter": 5,
        "height": 12,
        "base": [15, 10, 0],
        "axis": "Z",
        "operation": "cut",
        "targets": ["Spacer"]
      }
    }
  ]
}
EOF

cd solid-job && cat > design.json <<'EOF'
{
  "sources": [
    "spacer block dimensions 30 x 20 x 12 mm and a 5 mm hole straight down through the middle of the 30x20 face"
  ],
  "commands": [
    {
      "command": "solid.box",
      "params": {
        "length": 30,
        "width": 20,
        "height": 12,
        "corner": [0, 0, 0],
        "body_name": "Spacer"
      }
    },
    {
      "command": "solid.cylinder",
      "params": {
        "diameter": 5,
        "height": 12,
        "base": [15, 10, 0],
        "axis": "Z",
        "operation": "cut",
        "targets": ["Spacer"]
      }
    }
  ]
}
EOF

bash -c 'cat > solid-job/design.json <<EOF
{
  "sources": [
    "Request: washer 20 mm across",
    "Request: thickness 2 mm",
    "Request: hole diameter 8.4 mm"
  ],
  "commands": [
    {"command": "sketch.create", "params": {"plane": "XY", "name": "Washer"}},
    {"command": "sketch.circle.center", "params": {"center": [10, 10], "diameter": 20}},
    {"command": "sketch.finish", "params": {}},
    {"command": "solid.extrude", "params": {"distance": 2, "body_name": "Washer"}},
    {"command": "solid.cylinder", "params": {"diameter": 8.4, "height": 2, "base": [10, 10, 0], "axis": "Z", "operation": "cut", "targets": ["Washer"]}}
  ]
}
EOF'
